  (* [comment removed for export] *)
  Section STREAM.
  Variables (k SE OPk : Z) (ws : list word) (w120 w128 : word).
  Hypothesis K4 : 0 <= k < 4.
  Hypothesis HSE : DST <= OPk <= SE.
  Hypothesis HSE2 : SE <= DST + dcap.
  Hypothesis WOP : nth_error ws (Z.to_nat (4 + k)) = Some (Z_to_bv 64 OPk).
  Notation Z4Mk mm := (Z4M mm w120 w128 (Z_to_bv 64 0x20d84) ws).

  (* [comment removed for export] *)
  Notation STA pc mm x1 x9 a0 a1 a2 a3 x21 x23 x24 x25 x26 x28 x31 :=
    (MS (mkR x1 (Z_to_bv 64 SPF) gp tp (Z_to_bv 64 k) (Z_to_bv 64 seg) (Z_to_bv 64 64) (Z_to_bv 64 SE) x9 a0 a1 a2 a3
             (Z_to_bv 64 (SP + -136)) (Z_to_bv 64 (SP + -256)) (Z_to_bv 64 AZ4_DBC) (Z_to_bv 64 8)
             (Z_to_bv 64 (SP + -224 + 8 * k)) (Z_to_bv 64 OPk) (Z_to_bv 64 SS) x21 (Z_to_bv 64 (SS + 8)) x23 x24 x25 x26
             (Z_to_bv 64 2147450880) x28 (Z_to_bv 64 2) (Z_to_bv 64 4) x31)
        FR (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  (* [comment removed for export] *)
  Hypothesis CONT : forall mm (x1 x9 a1 a3 x21 x23 x24 x26 x28 x31 : word),
    Z4M mm w120 w128 (Z_to_bv 64 0x20d84) (upd ws (Z.to_nat (4 + k)) (Z_to_bv 64 SE)) ->
    evtF asegs RNG POST (STA 0x87224 mm x1 x9 (Z_to_bv 64 SE) a1 (Z_to_bv 64 SE) a3 x21 x23 x24 (Z_to_bv 64 0x20d84) x26 x28 x31).

  (* [comment removed for export] *)
  Lemma z4f_next : forall p mm (x1 x9 a0 a1 a3 x21 x23 x24 x25 x26 x28 x31 : word),
    Z4Mk mm -> OPk <= p <= SE ->
